-- Flowable 集成测试（H2 LEGACY 模式）使用的业务表，不支持表注释语法
CREATE TABLE IF NOT EXISTS "bpm_process_definition_info" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "process_definition_id" varchar(64) NOT NULL,
    "model_id" varchar(64) NOT NULL,
    "model_type" tinyint NOT NULL,
    "category" varchar(64),
    "icon" varchar(512),
    "description" varchar(255),
    "form_type" tinyint,
    "form_id" bigint,
    "form_conf" varchar(1000),
    "form_fields" varchar(5000),
    "form_custom_create_path" varchar(255),
    "form_custom_view_path" varchar(255),
    "simple_model" varchar(10000),
    "visible" bit NOT NULL DEFAULT TRUE,
    "sort" bigint,
    "start_user_ids" varchar(255),
    "start_dept_ids" varchar(255),
    "manager_user_ids" varchar(255),
    "allow_cancel_running_process" bit,
    "allow_withdraw_task" bit,
    "process_id_rule" varchar(255),
    "auto_approval_type" tinyint,
    "title_setting" varchar(512),
    "summary_setting" varchar(512),
    "process_before_trigger_setting" varchar(512),
    "process_after_trigger_setting" varchar(512),
    "task_before_trigger_setting" varchar(512),
    "task_after_trigger_setting" varchar(512),
    "print_template_setting" varchar(512),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);
